class Solution {
public:
    string addBinary(string a, string b) {
        string res;
        int i = (int)a.size() - 1;
        int j = (int)b.size() - 1;
        int carry = 0;
        while (i >= 0 || j >= 0 || carry) {
            int sum = carry;
            if (i >= 0) sum += a[i--] - '0';
            if (j >= 0) sum += b[j--] - '0';
            res.push_back(char('0' + (sum % 2)));
            carry = sum / 2;
        }
        reverse(res.begin(), res.end());
        return res;
    }
};
